using namespace lang;
using namespace lang::hir;
std::string q(const std::string &s) { auto *j=json_object_new_string_len(s.data(),s.size()); std::string r=json_object_to_json_string_ext(j,JSON_C_TO_STRING_PLAIN); json_object_put(j); return r; }
std::string b(bool x) { return x?"true":"false"; }
template<class T> std::string ids(const std::vector<T>&v) { std::string s="[";for(auto x:v){if(s.size()>1)s+=",";s+=std::to_string(x.value);}return s+"]"; }
template<class T> std::string opt(std::optional<T> v){return v?"option.Option[usize].Some("+std::to_string(v->value)+")":"option.Option[usize].None";}
std::string ref(modules::NodeRef r){if(r.module.value!=0||r.file!=0)throw std::runtime_error("fixture is not one module/file");return "model.NodeRef(module:0,file:0,node:"+std::to_string(r.node.value)+")";}
std::string span(SourceSpan s){return "model.Span(snapshot:"+std::to_string(s.snapshot.value)+",begin_byte:"+std::to_string(s.begin_byte)+",end_byte:"+std::to_string(s.end_byte)+")";}
std::string src(Source s){return "hir.HirSource(node:"+ref(s.node)+",span:"+span(s.span)+")";}
const char* modes[]={"Ordinary","Inout","Move"};
std::string mode(ParamMode m){return std::string("model.ParamMode.")+modes[int(m)];}
std::string owner(OwnerRef r){const char* names[]={"Binding","Temporary","ReturnOutput","ErrorOutput","Iteration"};return "hir.OwnerRef(kind:hir.OwnerKind."+std::string(names[int(r.kind)])+",identity:"+std::to_string(r.identity)+")";}
std::string steps(const std::vector<CleanupStep>&v){const char* names[]={"SaveOutput","EndBorrow","DestroyIfLive","Defer","EndIteration"};std::string r="[";for(auto x:v){if(r.size()>1)r+=",";r+="hir.CleanupStep(kind:hir.CleanupKind."+std::string(names[int(x.kind)])+",owner:"+owner(x.owner)+",type_id:"+std::to_string(x.type.value)+")";}return r+"]";}
std::string params(const std::vector<Parameter>&v){std::string r="[";for(auto x:v){if(r.size()>1)r+=",";r+="hir.Parameter(symbol:"+std::to_string(x.symbol.value)+",label:"+q(x.label)+")";}return r+"]";}
std::string fn(const HirFunction&f){if(!f.captures.empty()||f.async)throw std::runtime_error("unexpected capture/async");return "hir.HirFunction(symbol:"+std::to_string(f.symbol.value)+",signature:"+std::to_string(f.signature.value)+",parameters:"+params(f.parameters)+",body:"+std::to_string(f.body.value)+",scope:"+std::to_string(f.scope.value)+",source:"+src(f.source)+",captures:[],is_async:false)";}
std::string args(const std::vector<CallArg>&v){std::string r="[";for(auto a:v){if(r.size()>1)r+=",";r+="hir.CallArg(source_index:"+std::to_string(a.source_index)+",parameter_index:"+std::to_string(a.parameter_index)+",label:"+(a.label?"option.Option[string].Some("+q(*a.label)+")":"option.Option[string].None")+",mode:"+mode(a.mode)+",expression:"+std::to_string(a.expression.value)+")";}return r+"]";}
std::string data(const HirNode&n){
 if(std::holds_alternative<Block>(n.data))return "hir.NodeData.Block(hir.Block())";
 if(auto*x=std::get_if<Read>(&n.data))return "hir.NodeData.Read(hir.Read(symbol:"+std::to_string(x->symbol.value)+"))";
 if(auto*x=std::get_if<Return>(&n.data))return "hir.NodeData.Return(hir.Return(function:"+std::to_string(x->function.value)+"))";
 if(auto*x=std::get_if<Binding>(&n.data))return "hir.NodeData.Binding(hir.Binding(symbol:"+std::to_string(x->symbol.value)+",writable:"+b(x->writable)+"))";
 if(auto*x=std::get_if<BoolLiteral>(&n.data))return "hir.NodeData.BoolLiteral(hir.BoolLiteral(value:"+b(x->value)+"))";
 if(auto*x=std::get_if<IntegerLiteral>(&n.data))return "hir.NodeData.IntegerLiteral(hir.IntegerLiteral(decimal:"+q(x->decimal)+",bits:"+std::to_string(x->bits)+"))";
 if(auto*x=std::get_if<Call>(&n.data)){
  if(x->kind!=CalleeKind::direct||x->callee||x->binding||x->c_callable||x->system||!x->omitted.empty())throw std::runtime_error("unexpected callee variant");
  return "hir.NodeData.Call(hir.Call(kind:hir.CalleeKind.Direct,signature:"+std::to_string(x->signature.value)+",direct_symbol:"+opt(x->direct_symbol)+",callee:option.Option[usize].None,args:"+args(x->args)+",type_args:"+ids(x->type_args)+",binding:option.Option[usize].None,c_callable:option.Option[u32].None,omitted:[],system:option.Option[u32].None))";
 }
 throw std::runtime_error("unhandled real node kind "+std::to_string(int(n.kind())));
}
void emit(const HirModule&m,std::ostream&o){
 if(!m.nominals.empty()||!m.traits.empty()||!m.impls.empty()||!m.foreign_bindings.empty()||!m.resolved->deferred_members.empty()||!m.resolved->self_parameters.empty())throw std::runtime_error("unexpected fixture metadata");
 o<<"// Generated exactly from real C++ resolve/check output; no verifier replaced.\npackage app;\nimport \"app/wzcc/model\" as model;\nimport \"app/wzcc/hir\" as hir;\nimport \"app/wzcc/types\" as types;\nimport \"std/vec\" as vec;\nimport \"std/option\" as option;\nfunc build_generated(parsed model.ParseResult) hir.HirModule throws types.Error {\nvar project=model.empty_project();\nproject.modules=[model.Module(id:0,logical_path:\"app\",identity:\"app\",package_name:\"app\",files:[0],imports:[],foreign_exports:[],binding:option.Option[model.BindingModuleRef].None,c_binding:option.Option[usize].None)];\nproject.files=[parsed];\nlet resolved=model.ResolvedProject(project:project,symbols:[";
 const char* symbols[]={"Value","Constant","Function","Type","Trait","TypeParameter","Module","Field","Variant","BuiltinType","BuiltinFunction"};
 bool first=true;for(auto&s:m.resolved->symbols){if(!first)o<<",";first=false;if(s.target||s.foreign)throw std::runtime_error("foreign symbol");o<<"model.Symbol(id:"<<s.id.value<<",name:"<<q(s.name)<<",kind:model.SymbolKind."<<symbols[int(s.kind)]<<",module:"<<s.module.value<<",definition:"<<(s.definition?"option.Option[model.NodeRef].Some("+ref(*s.definition)+")":"option.Option[model.NodeRef].None")<<",declaration:"<<(s.declaration?"option.Option[model.Span].Some("+span(*s.declaration)+")":"option.Option[model.Span].None")<<",exported:"<<b(s.exported)<<",target:option.Option[usize].None,foreign:option.Option[model.ForeignExportRef].None)";}
 o<<"],occurrences:[";first=true;for(auto x:m.resolved->occurrences){if(!first)o<<",";first=false;o<<"model.Occurrence(source:"<<ref(x.source)<<",symbol:"<<x.symbol.value<<",span:"<<span(x.span)<<")";}o<<"],deferred_members:[],self_parameters:[]);\nvar module=hir.empty_module(resolved,0,model.CheckConfig(backend:model.Backend.Native,word_bits:64));\nvar context=types.context();\n";
 const char* kinds[]={"Unit","Bool","SignedInt","UnsignedInt","Float","String","Isize","Usize","Function","NominalStruct","NominalEnum","TypeParameter","ForeignOpaque","Error","Vec","ForeignCallable","CForeignPointer","CForeignBuffer","CForeignRecord","CForeignResource","CForeignCallback","CForeignOpaque","ThreadHandle","MutexHandle","CondvarHandle","AtomicI64Handle","IpcHandle","Slice","Weak","Task","TraitObject"};
 for(size_t i=1;i<=m.types.size();++i){auto&t=*m.types.find(TypeId{uint32_t(i)});o<<"let type_"<<i<<"=types.intern(inout context,model.Type(kind:model.TypeKind."<<kinds[int(t.kind)]<<",bits:"<<t.bits<<",declaration:"<<t.declaration.value<<",binding:"<<t.binding.value<<",parameters:[";first=true;for(auto p:t.parameters){if(!first)o<<",";first=false;o<<"model.ParameterType(mode:"<<mode(p.mode)<<",type_id:"<<p.type.value<<")";}o<<"],result:"<<t.result.value<<",throws_type:"<<opt(t.throws_type)<<",type_args:"<<ids(t.type_args)<<",c_type:"<<t.c_type<<"));\n";}
 o<<"module.types=context;\nmodule.functions=[";first=true;for(auto&f:m.functions){if(!first)o<<",";first=false;o<<fn(f);}o<<"];\nmodule.templates=[";first=true;for(auto&t:m.templates){if(!first)o<<",";first=false;o<<"hir.FunctionTemplate(function:"<<fn(t.function)<<",params:[";bool f2=true;for(auto p:t.params){if(p.trait)throw std::runtime_error("unexpected constraint");if(!f2)o<<",";f2=false;o<<"hir.GenericParam(symbol:"<<p.symbol.value<<",trait_ref:option.Option[hir.TraitRef].None,source:"<<src(p.source)<<")";}o<<"])";}o<<"];\nmodule.instances=[";first=true;for(auto&i:m.instances){if(!first)o<<",";first=false;o<<"hir.FunctionInstance(symbol:"<<i.symbol.value<<",origin:"<<i.origin.value<<",type_args:"<<ids(i.type_args)<<",renamed:[";bool f2=true;for(auto [a,z]:i.renamed){if(!f2)o<<",";f2=false;o<<"hir.SymbolRename(origin:"<<a.value<<",replacement:"<<z.value<<")";}o<<"],target:model.CheckConfig(backend:model.Backend.Native,word_bits:64))";}o<<"];\nmodule.nodes=[";
 first=true;for(auto&n:m.nodes){if(!n.exits.empty())throw std::runtime_error("expected trivial fixture exits");if(!first)o<<",";first=false;o<<"hir.HirNode(type_id:"<<n.type.value<<",source:"<<src(n.source)<<",scope:"<<n.scope.value<<",children:"<<ids(n.children)<<",data:"<<data(n)<<",errors:"<<ids(n.errors)<<",exits:[])";}o<<"];\nmodule.scopes=[";first=true;for(auto&s:m.scopes){if(!first)o<<",";first=false;o<<"hir.HirScope(function:"<<s.function.value<<",parent:"<<opt(s.parent)<<",source:"<<src(s.source)<<")";}o<<"];\nmodule.ownership=hir.Ownership(uses:[";
 first=true;const char* uses[]={"Borrow","Copy","Take","Inout"};for(auto x:m.ownership.uses){if(!first)o<<",";first=false;o<<"hir.ValueUse(consumer:"<<x.consumer.value<<",operand:"<<x.operand<<",kind:hir.UseKind."<<uses[int(x.kind)]<<",root:"<<opt(x.root)<<",type_id:"<<x.type.value<<",destination:"<<opt(x.destination)<<")";}o<<"],temporaries:[";first=true;for(auto x:m.ownership.temporaries){if(!first)o<<",";first=false;o<<"hir.Temporary(producer:"<<x.producer.value<<",full_expression:"<<x.full_expression.value<<",type_id:"<<x.type.value<<")";}o<<"],locals:[";first=true;for(auto x:m.ownership.locals){if(!first)o<<",";first=false;o<<"hir.LocalLifetime(symbol:"<<x.symbol.value<<",scope:"<<x.scope.value<<",type_id:"<<x.type.value<<",order:"<<x.order<<",mode:"<<mode(x.mode)<<",read_only_capture:"<<b(x.read_only_capture)<<")";}o<<"],full_expressions:[";first=true;for(auto x:m.ownership.full_expressions){if(!first)o<<",";first=false;o<<"hir.FullExpression(node:"<<x.node.value<<",actions:"<<steps(x.actions)<<")";}o<<"],calls:[";first=true;for(auto x:m.ownership.calls){if(!first)o<<",";first=false;o<<"hir.CallLifetime(node:"<<x.node.value<<",on_return:"<<steps(x.on_return)<<")";}o<<"]);\nreturn module;\n}\n";
}
int main(int argc,char**argv){try{
 if(argc!=3)return 2;std::ifstream in(argv[1]);std::string text((std::istreambuf_iterator<char>(in)),{});auto s=std::make_shared<SourceSnapshot>(FileId{1},RevisionId{1},SourceSnapshotId{1},"fixture.wz",text);auto l=lex(s);auto p=parse(*l.value);auto project=std::make_shared<modules::Project>();project->package_name="app";project->backend="native";project->word_bits=64;project->entry=ModuleId{0};modules::Module md;md.id=ModuleId{0};md.logical_path="app";md.identity="app";md.package_name="app";md.files.push_back(std::make_shared<const AstFile>(*p.value));project->modules.push_back(md);auto r=modules::resolve_project(project);if(!r.value)return 3;auto c=sema::check_types(r);if(!c.value){for(auto&d:c.diagnostics)std::cerr<<d.code<<":"<<d.message<<"\n";return 4;}auto&m=*c.value;auto v=verify(m,{},VerifyMode::backend);std::cout<<"CPP public verify="<<bool(v.value)<<" diagnostics="<<v.diagnostics.size()<<"\n";if(!v.value)return 5;
 std::cout<<dump(m);for(size_t i=0;i<m.nodes.size();++i)for(size_t j=0;j<i;++j){auto a=m.nodes[i].source,z=m.nodes[j].source;if(a.node.module==z.node.module&&a.node.file==z.node.file&&a.node.node==z.node.node&&a.span.snapshot==z.span.snapshot&&a.span.begin_byte==z.span.begin_byte&&a.span.end_byte==z.span.end_byte)std::cout<<"SOURCE_ALIAS first="<<j<<" later="<<i<<" source="<<a.node.node.value<<" kind="<<int(m.nodes[i].kind())<<"\n";}
 auto target=m.functions.back().body;for(auto id:m.nodes[target.value].children)if(std::holds_alternative<Return>(m.nodes[id.value].data))target=id;std::cout<<"TARGET_RETURN "<<target.value<<"\n";
 auto bad=m;bad.nodes[target.value].data=Return{SymbolId{99999}};auto bv=verify(bad,{},VerifyMode::backend);std::cout<<"CPP bad-return verify="<<bool(bv.value)<<" diagnostic="<<(bv.diagnostics.empty()?"none":bv.diagnostics[0].code+":"+bv.diagnostics[0].message)<<"\n";if(bv.value)return 6;
 bad=m;ExitPlan exit{ExitKind::return_,{},FunctionExit{m.functions.back().symbol},{ScopeId{99999}},{HirNodeId{99999}},true};bad.nodes[target.value].exits.push_back(exit);bv=verify(bad,{},VerifyMode::backend);std::cout<<"CPP bad-exit verify="<<bool(bv.value)<<" diagnostic="<<(bv.diagnostics.empty()?"none":bv.diagnostics[0].code+":"+bv.diagnostics[0].message)<<"\n";if(bv.value)return 7;
 std::ofstream out(argv[2]);emit(m,out);return 0;
 }catch(const std::exception&e){std::cerr<<e.what()<<"\n";return 9;}}
